                'În decembrie 2024, Torres a lucrat cu echipa de cercetare-dezvoltare de mediu Afarer pentru a configura modelul EcoTouring X de 12 picioare și 6 inci pentru monitorizarea costieră. Afarer a integrat o placă de montare pentru sonda YSI EXO2 (montată într-un puț personalizat care străbate nucleul plutei, permițând curgerea continuă a apei, fără rezistența unei sonde remorcate). Pluta a primit un braț de ridicare montat la prova (fibră de carbon, 1,5 kg, evaluat la 50 de livre), pentru coborârea și recuperarea unui sistem video subacvatic (GoPro HERO12 Black într-o carcasă backscatter, cu filtre roșii). O cutie de înregistrare a datelor montată la pupa (Pelican 1040) adăpostea un receptor GNSS și un modem celular, pentru încărcarea datelor în timp real prin platforma cloud a Mote. Trei prototipuri au fost implementate în ianuarie 2025, pentru un studiu de validare de 30 de zile, care a confirmat citirile sondei în limita a 2% față de citirile de pe bărci, la stații pereche. Mote a comandat 15 plute în valoare de 186.000 USD, finanțate de SBEP și de Gulf Research Program.',
