                'Afarer a proiectat Polar Explorer 12.0 cu adaptări specifice de Arctic — culoare portocaliu internațional strălucitoare (vizibilă pe gheață de la 2 km prin binoclu), benzi reflectorizante de clasă SOLAS, o buclă de salvare integrată evaluată la 600 kg (pentru recuperarea cu remorcarea de Zodiac) și un buzunar pentru baliza GPS în provă (Hurtigruten a furnizat unități Garmin inReach Mini 2). Pachetul includea o vestă de salvare gonflabilă compatibilă cu costumul etanș (Mustang Survival HIT, testată de Afarer pentru mobilitate în timpul vâslitului), un set de mănuși pogie din neopren (încălzitoare de mâini integrate în tubul vârstei) și un rucsac personalizat care încăpea în compartimentul de depozitare al unui Zodiac (dimensiune împachetată 60x30x30 cm). Sistemul de desfășurare din Zodiac — un raft cu roată tip jockey, fixat pe pontonul Zodiacului, permitea unui singur ghid să gliseze plutele în apă fără a le ridica.',
